test:
game = ConnectKGame(3, 4, 3)
try:
    game.make_move(Player.O, 0)
except ValueError:
    pass
else:
    raise AssertionError('Expected ValueError')
try:
    game.make_move('X', 0)
except ValueError:
    pass
else:
    raise AssertionError('Expected ValueError')
try:
    game.make_move(Player.X, -1)
except ValueError:
    pass
else:
    raise AssertionError('Expected ValueError')
try:
    game.make_move(Player.X, 4)
except ValueError:
    pass
else:
    raise AssertionError('Expected ValueError')
assert game.make_move(Player.X, 0) is GameStatus.IN_PROGRESS
try:
    game.make_move(Player.X, 1)
except ValueError:
    pass
else:
    raise AssertionError('Expected ValueError')
assert game.make_move(Player.O, 3) is GameStatus.IN_PROGRESS
assert game.make_move(Player.X, 1) is GameStatus.IN_PROGRESS
assert game.make_move(Player.O, 3) is GameStatus.IN_PROGRESS
assert game.make_move(Player.X, 2) is GameStatus.PLAYER_X_WINS

game = ConnectKGame(2, 3, 3)
columns = [0, 1, 2, 0, 1, 2]
for turn, column in enumerate(columns):
    player = Player.X if turn % 2 == 0 else Player.O
    expected = GameStatus.DRAW if turn == len(columns) - 1 else GameStatus.IN_PROGRESS
    assert game.make_move(player, column) is expected, f'Unexpected status after move {turn + 1}'
try:
    game.make_move(Player.X, 0)
except ValueError:
    pass
else:
    raise AssertionError('Expected ValueError')

game = ConnectKGame(6, 7, 4)
columns = [0, 6, 1, 6, 2, 5, 3]
for turn, column in enumerate(columns):
    player = Player.X if turn % 2 == 0 else Player.O
    expected = GameStatus.PLAYER_X_WINS if turn == len(columns) - 1 else GameStatus.IN_PROGRESS
    assert game.make_move(player, column) is expected, f'Unexpected status after move {turn + 1}'
try:
    game.make_move(Player.O, 4)
except ValueError:
    pass
else:
    raise AssertionError('Expected ValueError')
try:
    game.make_move(Player.X, 4)
except ValueError:
    pass
else:
    raise AssertionError('Expected ValueError')

for rows, columns, k in [(0, 7, 4), (6, 0, 4), (6, 7, 0), (-1, 7, 4)]:
    try:
        ConnectKGame(rows, columns, k)
    except ValueError:
        pass
    else:
        raise AssertionError('Expected ValueError for nonpositive dimensions or K')
